import {
  SkuListInput,
  QuickOrderDisabledOverlay,
} from '@/b2b-quick-order/components';
import { useQuickOrderMultipleSku } from '@/b2b-quick-order/hooks';
import { QuickOrderMultipleSkuProps } from '@/b2b-quick-order/types';
import { config } from '@/b2b-quick-order/api/initialize';
import { Button } from '@adobe-commerce/elsie/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import { classes, Container, Slot } from '@adobe-commerce/elsie/lib';

export const QuickOrderMultipleSku: Container<QuickOrderMultipleSkuProps> = ({
  className,
  onChange,
  slots,
}) => {
  const isQuickOrderActive = config.getConfig().quickOrderActive;

  const t = useText({
    title: 'QuickOrder.SkuListInput.title',
    helperText: 'QuickOrder.SkuListInput.helperText',
    textAreaPlaceholder: 'QuickOrder.SkuListInput.textArea.placeholder',
    buttonText: 'QuickOrder.SkuListInput.button',
    label: 'QuickOrder.SkuListInput.textArea.label',
    disabledMessage: 'QuickOrder.QuickOrderItem.disabledMessage',
  });

  const { handleChange, textAreaValue, loading, handleAddToList } =
    useQuickOrderMultipleSku({
      onChange,
    });

  return (
    <div
      className={classes([
        'b2b-quick-order-quick-order-multiple-sku',
        className,
      ])}
      data-testid="storefrontQuickOrderTest"
    >
      <QuickOrderDisabledOverlay
        isDisabled={!isQuickOrderActive}
        message={t.disabledMessage}
      >
        <SkuListInput
          loading={loading}
          textAreaValue={textAreaValue}
          onChange={handleChange}
          t={t}
        />
        <Slot
          data-testid="addToListButtonTest"
          name="AddToListButton"
          slot={slots?.AddToListButton}
          context={{ handleAddToList, loading, textAreaValue }}
        >
          <Button
            onClick={() => handleAddToList()}
            disabled={loading || !textAreaValue.length}
          >
            {t.buttonText}
          </Button>
        </Slot>
      </QuickOrderDisabledOverlay>
    </div>
  );
};
